using PKHeX.Core;
using PokeRNGKit.SaveEditor;
using System.Text.Json;

internal static class SuperTrainingSessionTests
{
    private static readonly SuperTrainingEvent[][] Sequences=[[],[new("all")],[new("all"),new("all")],[new("none")],[new("none"),new("all")],[new("distribution",3,1),new("regular",0,1)]];
    private static PKM Entity(PKM p){p.Species=25;p.Language=2;p.OriginalTrainerName="TEST";p.Nickname="TEST";p.CurrentLevel=25;var r=(ISuperTrainRegimen)p;r.SuperTrainBitFlags=0xA5A5A5A7;r.DistTrainBitFlags=0xA5C9;r.SecretSuperTrainingUnlocked=false;r.SuperTrainSupremelyTrained=true;if(p is PK6 b){b.TrainingBag=255;b.TrainingBagHits=255;}p.ResetPartyStats();p.Stat_HPCurrent=Math.Max(1,p.Stat_HPMax/2);p.Status_Condition=8;p.RefreshChecksum();return p;}
    internal static void Run(){
        foreach(PKM entity in new PKM[]{Entity(new PK6()),Entity(new PK7())})foreach(bool party in new[]{false,true})foreach(bool encrypted in new[]{false,true}){
            byte[] input=StandalonePokemon.Serialize(entity,party,encrypted),original=input.ToArray();var target=new SuperTrainingTarget("file",FileName:"entity."+entity.GetType().Name.ToLowerInvariant(),InputEncrypted:encrypted,UseFileFormat:true);
            var catalog=SuperTrainingSession.Read(input,target);Check(catalog.Stored.Complete && !catalog.Stored.Unlocked,"Stored metadata separate from normalized draft");
            var publicCatalog=JsonSerializer.Deserialize(SaveService.ReadPokemonSuperTraining(input,JsonSerializer.Serialize(target,SaveJsonContext.Default.SuperTrainingTarget)),SaveJsonContext.Default.SuperTrainingCatalog)!;Check(publicCatalog.Raw==catalog.Raw&&publicCatalog.Stored.Complete&&publicCatalog.Rows.Length==36,"Public required JSON catalog");
            foreach(var events in Sequences){var request=new SuperTrainingRequest(catalog.SourceHash,target,new(events));var ticket=SuperTrainingSession.Prepare(input,request);Check(SuperTrainingSession.Commit(input,Confirm(ticket)).AsSpan().SequenceEqual(StandalonePokemon.Serialize(PokemonSuperTrainingTests.Oracle(entity,events),party,false)),"Every ordered sequence/full file oracle");VerifyDiff(ticket);if(entity is PK6&&events.Length==0)Check(ticket.ChangedRows.Any(i=>i>=18)&&ticket.ChangedFields.Contains("complete")&&ticket.ChangedFields.Contains("bag"),"Opening normalization visible in frozen preview");}
            var requestJson=JsonSerializer.Serialize(new SuperTrainingRequest(catalog.SourceHash,target,new([])),SaveJsonContext.Default.SuperTrainingRequest);var publicTicket=JsonSerializer.Deserialize(SaveService.PreviewPokemonSuperTraining(input,requestJson),SaveJsonContext.Default.SuperTrainingTicket)!;Check(SaveService.CommitPokemonSuperTraining(input,JsonSerializer.Serialize(Confirm(publicTicket),SaveJsonContext.Default.SuperTrainingConfirmation)).AsSpan().SequenceEqual(StandalonePokemon.Serialize(PokemonSuperTrainingTests.Oracle(entity,[]),party,false)),"Public required JSON full output");var failed=SuperTrainingSession.Prepare(input,new(catalog.SourceHash,target,new([])));Reject(()=>SaveService.PreviewPokemonSuperTraining(input,"{}"));Reject(()=>SuperTrainingSession.Commit(input,Confirm(failed)));Reject(()=>JsonSerializer.Deserialize("{}",SaveJsonContext.Default.SuperTrainingEvent));Reject(()=>JsonSerializer.Deserialize("{}",SaveJsonContext.Default.SuperTrainingConfirmation));
            Lifecycle(input,()=>SuperTrainingSession.Prepare(input,new(catalog.SourceHash,target,new([]))));Check(input.AsSpan().SequenceEqual(original),"Standalone original");Console.WriteLine($"PASS SuperTraining file {entity.GetType().Name}/party={party}/encrypted={encrypted}: public JSON/ordered full file oracle, stored/normalized differences, frozen lifecycle and original");
        }
        foreach(SaveFile seed in new SaveFile[]{new SAV6XY(File.ReadAllBytes(".tmp/pkhex-fixtures/X.sav")),new SAV6AO(File.ReadAllBytes(".tmp/pkhex-fixtures/OR.sav")),new SAV7SM(File.ReadAllBytes(".tmp/pkhex-fixtures/SN.sav")),new SAV7USUM(File.ReadAllBytes(".tmp/pkhex-fixtures/US.sav")),new SAV6AODemo(new SAV6AODemo().Write().ToArray())}){
            var entity=Entity(seed.BlankPKM);if(seed.HasBox)seed.SetBoxSlotAtIndex(entity,0,0,EntityImportSettings.None);seed.SetPartySlotAtIndex(entity,0,EntityImportSettings.None);byte[] input=seed.Write().ToArray(),original=input.ToArray();
            foreach(int box in seed.HasBox?new[]{-1,0}:new[]{-1}){var target=new SuperTrainingTarget("save",Box:box,Slot:0);var before=PokemonEditing.Read(seed,box,0);var catalog=PokemonSuperTraining.Read(before,Br4Editing.Hash(input));
                foreach(var events in Sequences){var request=new SuperTrainingRequest(catalog.SourceHash,target,new(events));var ticket=SuperTrainingSession.Prepare(seed,input,request);var copy=seed.Clone();var expected=PokemonSuperTrainingTests.Oracle(before,events);if(box==-1)copy.SetPartySlotAtIndex(expected,0,EntityImportSettings.None);else copy.SetBoxSlotAtIndex(expected,0,0,EntityImportSettings.None);Check(SuperTrainingSession.Commit(input,Confirm(ticket)).AsSpan().SequenceEqual(copy.Write().Span),"Every save sequence/full file oracle");VerifyDiff(ticket);}
                Lifecycle(input,()=>SuperTrainingSession.Prepare(seed,input,new(catalog.SourceHash,target,new([]))));Check(seed.Write().Span.SequenceEqual(original)&&input.AsSpan().SequenceEqual(original),"Typed save/source immutable");Console.WriteLine($"PASS SuperTraining typed {seed.GetType().Name}/box={box}: ordered full save oracle, preview differences, frozen target lifecycle and original; public recognition/real save not accepted");
            }
        }
    }
    private static void VerifyDiff(SuperTrainingTicket t){byte[] a=Convert.FromHexString(t.Before.Raw),b=Convert.FromHexString(t.Result.Raw);Check(t.ChangedFlags.SequenceEqual(Enumerable.Range(0,a.Length*8).Where(i=>((a[i>>3]^b[i>>3])&(1<<(i&7)))!=0)),"Exact raw bit differences");Check(t.ChangedRows.SequenceEqual(Enumerable.Range(0,36).Where(i=>t.Before.Rows[i].StoredFlag!=t.Result.Rows[i].StoredFlag)),"Exact stored row changes");}
    private static SuperTrainingConfirmation Confirm(SuperTrainingTicket t)=>new(t.Token,t.SourceHash,t.TargetHash,t.Target);
    private static void Lifecycle(byte[] input,Func<SuperTrainingTicket> prepare){var old=prepare();var fresh=prepare();SuperTrainingSession.Discard(old.Token);Reject(()=>SuperTrainingSession.Commit(input,Confirm(old)));foreach(var target in new[]{fresh.Target with{Kind="other"},fresh.Target with{Box=2},fresh.Target with{Slot=2},fresh.Target with{FileName="other.pk6"},fresh.Target with{InputEncrypted=!fresh.Target.InputEncrypted},fresh.Target with{UseFileFormat=!fresh.Target.UseFileFormat}})Reject(()=>SuperTrainingSession.Commit(input,Confirm(fresh) with{Target=target}));var stale=input.ToArray();stale[0]^=1;Reject(()=>SuperTrainingSession.Commit(stale,Confirm(fresh)));SuperTrainingSession.Commit(input,Confirm(fresh));Reject(()=>SuperTrainingSession.Commit(input,Confirm(fresh)));var fail=prepare();Reject(()=>SuperTrainingSession.Prepare(input,new("stale",fail.Target,new([]))));Reject(()=>SuperTrainingSession.Commit(input,Confirm(fail)));var canceled=prepare();SuperTrainingSession.Discard(canceled.Token);Reject(()=>SuperTrainingSession.Commit(input,Confirm(canceled)));}
    private static void Check(bool value,string message){if(!value)throw new Exception(message);}
    private static void Reject(Action action){try{action();}catch(ArgumentException){return;}catch(JsonException){return;}throw new Exception("Invalid SuperTraining session accepted");}
}
